import Database from 'better-sqlite3';import {AutomationEventIngestor} from '../../src/automation/events/event-ingestor.ts';import {AtgTankEngine} from '../../src/automation/atg/atg-tank-engine.ts';
const db=new Database(process.argv[2]);db.pragma('foreign_keys=ON');db.pragma('busy_timeout=10000');const ingestor=new AutomationEventIngestor(db,(e,id)=>new AtgTankEngine(db).process(e,id)),now=new Date().toISOString();try{ingestor.ingest({eventId:'ATG-CONCURRENT',eventType:'ATG_TANK_READING',controllerId:'ctrl-1',externalDeviceId:'TANK-01',deviceType:'TANK',sourceSequence:'9000',sourceOccurredAt:now,receivedAt:now,schemaVersion:1,payload:{externalTankId:'TANK-01',productCode:'PMS',volume:32000,volumeUnit:'L'}});}finally{db.close();}
